use rle::{encode, decode};

#[test]
fn test_encode_basic() {
    assert_eq!(encode("aaabbc"), "3a2b1c");
    assert_eq!(encode("abcd"), "1a1b1c1d");
}

#[test]
fn test_encode_empty() {
    assert_eq!(encode(""), "");
}

#[test]
fn test_decode_basic() {
    assert_eq!(decode("3a2b1c"), "aaabbc");
    assert_eq!(decode("1a1b1c1d"), "abcd");
}

#[test]
fn test_decode_empty() {
    assert_eq!(decode(""), "");
}

#[test]
fn test_roundtrip() {
    let inputs = ["aaabbc", "abcd", "aaaaaa", "xyzz"];
    for s in &inputs {
        assert_eq!(decode(&encode(s)), *s);
    }
}

